parameters.cypherQuery:
MATCH (a1:Author)<-[:AUTHOR]-(:Article)-[:AUTHOR]->(a2:Author)
WITH DISTINCT a1, a2
RETURN gds.graph.project(
  $graph_name,
  a1,
  a2,
  {
    sourceNodeLabels: labels(a1),
    targetNodeLabels: labels(a2),
    relationshipType: 'COAUTHORED'
  },
  { undirectedRelationshipTypes: ['COAUTHORED'] }
)

MATCH (a:Author)<-[:AUTHOR]-(:Article)-[:AUTHOR]->(b:Author)
WHERE id(a) < id(b)
RETURN gds.graph.project(
  $graph_name,
  a,
  b,
  {
    sourceNodeLabels: labels(a),
    targetNodeLabels: labels(b),
    relationshipType: 'CO_AUTHOR'
  },
  { undirectedRelationshipTypes: ['CO_AUTHOR'] }
)

